const input = $input.first().json;

console.log('\n🔍 АНАЛИЗ ОТВЕТА ОТ INSTAGRAM:');
console.log('   Input type:', typeof input);
console.log('   Input keys:', input ? Object.keys(input) : 'null');
console.log('   Has data:', input && input.data ? 'yes' : 'no');
console.log('   Data length:', input && input.data ? input.data.length : 0);
console.log('   Has paging:', input && input.paging ? 'yes' : 'no');

if (!input) {
  console.log('❌ Нет ответа от Instagram API');
  return { json: { skip: true, reason: 'no_response' } };
}

if (!input.data || input.data.length === 0) {
  console.log('⚠️ Нет постов в ответе от Instagram');
  console.log('   Full response:', JSON.stringify(input).substring(0, 500));
  return { json: { skip: true, reason: 'no_posts' } };
}

const posts = input.data;
console.log(`\n✅ Получено постов: ${posts.length}`);

// Показываем ПЕРВЫЙ пост полностью для отладки
if (posts.length > 0) {
  console.log('\n📋 ПЕРВЫЙ ПОСТ (полностью):');
  console.log(JSON.stringify(posts[0], null, 2));
  console.log('\n📋 Ключи первого поста:', Object.keys(posts[0]));
}

// Проверяем пагинацию
if (input.paging && input.paging.next) {
  console.log('\n⚠️ Есть еще посты! URL следующей страницы:', input.paging.next.substring(0, 100) + '...');
  console.log('   Для загрузки всех постов нужно добавить пагинацию');
}

// Возвращаем массив постов для дальнейшей обработки
// ВАЖНО: проверяем все возможные варианты названий полей
return posts.map(post => {
  const result = {
    json: {
      post_id: post.id || post.post_id || '',
      caption: post.caption || post.caption_text || '',
      media_type: post.media_type || post.type || 'UNKNOWN',
      media_url: post.media_url || post.thumbnail_url || post.image_url || '',
      posted_at: post.timestamp || post.created_time || post.posted_at || '',
      permalink: post.permalink || post.link || ''
    }
  };

  // Логируем, если какие-то поля пустые
  if (!result.json.caption && post.caption) {
    console.log(`⚠️ Post ${result.json.post_id}: caption не найден, но есть в исходных данных`);
  }
  if (!result.json.media_url && (post.media_url || post.thumbnail_url)) {
    console.log(`⚠️ Post ${result.json.post_id}: media_url не найден, но есть в исходных данных`);
  }

  return result;
});

// Обрабатываем ВСЕ посты с их insights
// В n8n, когда нода получает данные от нескольких предыдущих нод,
// нужно правильно сопоставить посты и insights

// Получаем все посты из ноды "🔄 Transform Posts"
let allPosts = [];
try {
  const transformNode = $('🔄 Transform Posts');
  if (transformNode) {
    allPosts = transformNode.all().map(item => item.json);
    console.log(`\n✅ Получено постов из "🔄 Transform Posts": ${allPosts.length}`);
  } else {
    console.log('⚠️ Нода "🔄 Transform Posts" не найдена, используем текущий input');
    allPosts = $input.all().map(item => item.json);
  }
} catch (e) {
  console.log('⚠️ Ошибка получения постов:', e.message);
  allPosts = $input.all().map(item => item.json);
}

// Получаем все insights из ноды "📊 Get Insights"
let allInsights = [];
try {
  const insightsNode = $('📊 Get Insights');
  if (insightsNode) {
    allInsights = insightsNode.all().map(item => item.json);
    console.log(`\n✅ Получено insights из "📊 Get Insights": ${allInsights.length}`);
  } else {
    console.log('⚠️ Нода "📊 Get Insights" не найдена');
  }
} catch (e) {
  console.log('⚠️ Ошибка получения insights:', e.message);
}

console.log(`\n🔍 MERGE INSIGHTS - Обработка ${allPosts.length} постов`);

function extractMetric(data, metricName) {
  if (!data || !data.data || !Array.isArray(data.data)) return 0;
  const metric = data.data.find(m => m.name === metricName);
  return metric?.values?.[0]?.value || 0;
}

// Период фильтрации: 1-22 января 2026
const periodStart = new Date('2026-01-01T00:00:00.000Z');
const periodEnd = new Date('2026-01-22T23:59:59.999Z');

// Обрабатываем каждый пост
const results = [];
let inPeriodCount = 0;
let outOfPeriodCount = 0;

for (let i = 0; i < allPosts.length; i++) {
  const postData = allPosts[i];

  // Пытаемся найти соответствующий insights (по индексу или по post_id)
  let insights = {};
  if (i < allInsights.length) {
    insights = allInsights[i];
  } else {
    // Пытаемся найти по post_id
    const matchingInsights = allInsights.find(ins => {
      // Insights может содержать информацию о post_id в URL или других полях
      return true; // Берем первый доступный
    });
    if (matchingInsights) insights = matchingInsights;
  }

  // Обрабатываем posted_at - конвертируем в правильный формат
  let postedAt = postData.posted_at;
  if (!postedAt || postedAt === '') {
    postedAt = new Date().toISOString();
    console.log(`⚠️ Post ${postData.post_id}: нет timestamp, используем текущую дату`);
  } else {
    try {
      const date = new Date(postedAt);
      if (isNaN(date.getTime())) {
        console.log(`⚠️ Post ${postData.post_id}: невалидная дата ${postedAt}, используем текущую`);
        postedAt = new Date().toISOString();
      } else {
        postedAt = date.toISOString();
      }
    } catch (e) {
      console.log(`⚠️ Post ${postData.post_id}: ошибка парсинга даты ${postedAt}:`, e.message);
      postedAt = new Date().toISOString();
    }
  }

  // Проверяем, попадает ли пост в период 1-22 января
  const postDate = new Date(postedAt);
  const isInPeriod = postDate >= periodStart && postDate <= periodEnd;

  if (!isInPeriod) {
    outOfPeriodCount++;
    const dateStr = postDate.toISOString().split('T')[0];
    console.log(`⏭️ Post ${postData.post_id}: Дата ${dateStr} - ВНЕ ПЕРИОДА 1-22 янв, пропускаем`);
    continue; // Пропускаем посты вне периода
  }

  inPeriodCount++;

  const reach = extractMetric(insights, 'reach');

  const result = {
    post_id: postData.post_id,
    caption: postData.caption || '',
    media_type: postData.media_type || 'UNKNOWN',
    media_url: postData.media_url || '',
    posted_at: postedAt,
    permalink: postData.permalink || '',
    reach: reach,
    impressions: extractMetric(insights, 'impressions') || reach,
    likes: extractMetric(insights, 'likes'),
    comments: extractMetric(insights, 'comments'),
    shares: extractMetric(insights, 'shares'),
    saves: extractMetric(insights, 'saved'),
    leads_count: 0,
    paid_leads: 0,
    revenue: 0
  };

  const dateStr = postDate.toISOString().split('T')[0];
  console.log(`✅ Post ${result.post_id}: Дата ${dateStr} | В ПЕРИОДЕ 1-22 янв | ${result.impressions} показов, ${result.reach} охват, ${result.likes} лайков`);

  results.push({ json: result });
}

console.log(`\n📊 ИТОГО:`);
console.log(`   Всего постов: ${allPosts.length}`);
console.log(`   В периоде 1-22 янв: ${inPeriodCount}`);
console.log(`   Вне периода: ${outOfPeriodCount}`);
console.log(`   Обработано и возвращено: ${results.length}`);

if (results.length === 0) {
  console.log('\n⚠️ Нет постов в периоде 1-22 января!');
  console.log('   Проверь даты постов в Instagram');
}

return results;

// Обрабатываем ВСЕ посты из предыдущей ноды
const allInputs = $input.all();
console.log('\n🔍 ПОДГОТОВКА ДЛЯ SUPABASE - Входные данные:');
console.log('   Количество элементов:', allInputs.length);

if (allInputs.length === 0) {
  console.log('❌ Нет входных данных');
  return { json: { error: 'no_input_data' } };
}

// Обрабатываем каждый пост
const results = [];

for (let i = 0; i < allInputs.length; i++) {
  const input = allInputs[i].json;
  console.log(`\n📋 Обработка поста ${i + 1}/${allInputs.length}: ${input.post_id || 'unknown'}`);

  // Проверяем, что post_id не пустой
  if (!input.post_id || input.post_id === '') {
    console.log(`   ❌ ОШИБКА: post_id пустой для поста ${i + 1}!`);
    console.log('   Входные данные:', JSON.stringify(input, null, 2));
    console.log('   Попытка получить post_id из других полей...');

    // Пробуем найти post_id в других полях
    const possiblePostId = input.id || input.post_id || input.media_id || '';
    if (possiblePostId) {
      console.log(`   Найден post_id в другом поле: ${possiblePostId}`);
      input.post_id = possiblePostId;
    } else {
      console.log('   ❌ post_id не найден ни в одном поле, пропускаем этот пост');
      continue;
    }
  }

  // Формируем объект для Supabase
  const supabaseData = {
    post_id: input.post_id || '',
    caption: input.caption || '',
    media_type: input.media_type || 'UNKNOWN',
    media_url: input.media_url || '',
    permalink: input.permalink || '',
    posted_at: input.posted_at || new Date().toISOString(),
    impressions: input.impressions || 0,
    reach: input.reach || 0,
    likes: input.likes || 0,
    comments: input.comments || 0,
    shares: input.shares || 0,
    saves: input.saves || 0,
    leads_count: 0,
    paid_leads: 0,
    revenue: 0,
    updated_at: new Date().toISOString()
  };

  // Проверяем, что все обязательные поля заполнены
  if (!supabaseData.post_id || supabaseData.post_id === '') {
    console.log(`   ❌ КРИТИЧЕСКАЯ ОШИБКА: post_id пустой для поста ${i + 1}!`);
    console.log('   Данные:', JSON.stringify(supabaseData, null, 2));
    continue;
  }

  console.log(`   ✅ Post ${supabaseData.post_id}: ${supabaseData.media_type} | ${supabaseData.posted_at.split('T')[0]}`);

  results.push({ json: supabaseData });
}

console.log(`\n📊 ИТОГО подготовлено для Supabase: ${results.length} постов`);
console.log(`   URL: https://pyscczcuersdjvpmkiec.supabase.co/rest/v1/instagram_posts_stats?on_conflict=post_id`);

if (results.length === 0) {
  console.log('\n❌ Нет постов для сохранения!');
  return { json: { error: 'no_posts_to_save' } };
}

return results;

// Обрабатываем ответ от Supabase
const input = $input.first();
const responseData = input.json;
const statusCode = input.statusCode || (input.headers && input.headers.status) || null;

console.log('\n🔍 ОБРАБОТКА ОТВЕТА ОТ SUPABASE:');
console.log('   HTTP Status Code:', statusCode);
console.log('   Response type:', typeof responseData);
console.log('   Is array:', Array.isArray(responseData));
console.log('   Response keys:', responseData && typeof responseData === 'object' ? Object.keys(responseData) : 'null');
console.log('   Full response:', JSON.stringify(responseData, null, 2));

// Проверяем HTTP статус
if (statusCode && (statusCode >= 200 && statusCode < 300)) {
  console.log(`\n✅ HTTP Status ${statusCode} - Запрос успешен!`);
} else if (statusCode && statusCode >= 400) {
  console.log(`\n❌ HTTP Status ${statusCode} - Ошибка запроса!`);
}

// Проверяем, есть ли ошибка в теле ответа
if (responseData && (responseData.error || responseData.message)) {
  console.log('\n❌ ОШИБКА ОТ SUPABASE:');
  console.log('   Error:', responseData.error || responseData.message);
  console.log('   Details:', responseData.details || responseData.hint || '');

  return {
    json: {
      success: false,
      error: responseData.error || responseData.message,
      details: responseData.details || responseData.hint || '',
      status_code: statusCode,
      timestamp: new Date().toISOString()
    }
  };
}

// Если HTTP статус успешный (200-299), считаем это успехом, даже если тело пустое
if (statusCode && statusCode >= 200 && statusCode < 300) {
  console.log(`\n✅ HTTP ${statusCode} - Данные успешно сохранены в Supabase!`);
}

// Supabase при успешном UPSERT может вернуть:
// 1. Пустой массив [] - это УСПЕХ (данные сохранены/обновлены)
// 2. Массив с объектом [{...}] - это УСПЕХ (данные возвращены)
// 3. Пустой объект {} - это УСПЕХ (данные сохранены)

if (Array.isArray(input)) {
  if (input.length === 0) {
    console.log('\n✅ УСПЕШНО СОХРАНЕНО в Supabase! (пустой массив = успех для UPSERT)');
    console.log('   Supabase вернул пустой массив - это нормально для успешного UPSERT');

    return {
      json: {
        success: true,
        posts_processed: 1,
        message: 'Данные успешно сохранены/обновлены (Supabase вернул пустой массив)',
        timestamp: new Date().toISOString()
      }
    };
  } else {
    console.log(`\n✅ УСПЕШНО СОХРАНЕНО в Supabase!`);
    console.log(`   Количество записей: ${input.length}`);
    console.log('   Сохраненная запись:', JSON.stringify(input[0], null, 2).substring(0, 500));

    return {
      json: {
        success: true,
        posts_processed: input.length,
        data: input[0] || null,
        timestamp: new Date().toISOString()
      }
    };
  }
}

// Если это пустой объект {} - это тоже успех
if (input && typeof input === 'object' && Object.keys(input).length === 0) {
  console.log('\n✅ УСПЕШНО СОХРАНЕНО в Supabase! (пустой объект = успех)');
  console.log('   Supabase вернул пустой объект - это нормально для успешного сохранения');

  return {
    json: {
      success: true,
      posts_processed: 1,
      message: 'Данные успешно сохранены (Supabase вернул пустой объект)',
      timestamp: new Date().toISOString()
    }
  };
}

// Если это объект с данными
if (input && typeof input === 'object' && Object.keys(input).length > 0) {
  console.log(`\n✅ УСПЕШНО СОХРАНЕНО в Supabase!`);
  console.log('   Сохраненная запись:', JSON.stringify(input, null, 2).substring(0, 500));

  return {
    json: {
      success: true,
      posts_processed: 1,
      data: input,
      timestamp: new Date().toISOString()
    }
  };
}

// Если input пустой или null - проверяем, может быть это успех
if (!input || input === null || input === undefined) {
  console.log('\n✅ УСПЕШНО СОХРАНЕНО в Supabase! (нет ответа = успех для UPSERT)');
  console.log('   Supabase не вернул данные - это нормально для успешного UPSERT');

  return {
    json: {
      success: true,
      posts_processed: 1,
      message: 'Данные успешно сохранены (Supabase не вернул ответ - это нормально)',
      timestamp: new Date().toISOString()
    }
  };
}

// Неизвестный формат ответа
console.log('\n⚠️ Неизвестный формат ответа от Supabase');
console.log('   Response:', JSON.stringify(input, null, 2));
return {
  json: {
    success: false,
    error: 'unknown_response_format',
    response: input,
    timestamp: new Date().toISOString()
  }
};

const items = $input.all();
const successCount = items.filter(item => item.json.success === true).length;
const errorCount = items.filter(item => item.json.success === false).length;

console.log(`\n✅ ИТОГОВЫЙ РЕЗУЛЬТАТ:`);
console.log(`   Успешно сохранено: ${successCount} постов`);
console.log(`   Ошибок: ${errorCount}`);

if (errorCount > 0) {
  console.log('\n❌ Ошибки при сохранении:');
  items.filter(item => item.json.success === false).forEach((item, idx) => {
    console.log(`   ${idx + 1}. ${item.json.error || 'Unknown error'}`);
  });
}

return {
  json: {
    success: errorCount === 0,
    posts_processed: successCount,
    errors: errorCount,
    timestamp: new Date().toISOString()
  }
};
